    { name: "MIT 8.701 — Introduction to Nuclear and Particle Physics", desc: "Course covering beta decay, the weak interaction and neutrino experiments.", url: "https://ocw.mit.edu/courses/8-701-introduction-to-nuclear-and-particle-physics-fall-2020/", type: "course", icon: "🎓" }
